#include "elit21/shopify/webhooks/RefundWebhookHandler.h"
namespace elit21::shopify::webhooks {RefundWebhookHandler::RefundWebhookHandler():platform::BusinessComponent("RefundWebhookHandler","Persistent Shopify webhook domain handler",platform::BusinessComponentSpec{"shopify","handle_webhook",{},true,false,16U*1024U*1024U}){}RefundWebhookHandler::RefundWebhookHandler(Database&database):RefundWebhookHandler(){database_=&database;}Result<void>RefundWebhookHandler::handle(const ShopifyWebhook&event){if(!database_)return Result<void>::failure("RefundWebhookHandler is not bound to Database");return persistWebhookTask(*database_,event,{ShopifyWebhookTopic::refunds_create});}platform::OperationResult RefundWebhookHandler::execute(const platform::OperationContext&context){auto r=executeBusiness(context);r.metrics["database_bound"]=database_?1.0:0.0;r.attributes["handler"]="RefundWebhookHandler";return r;}}
